// import type { ComponentStyleVariantConfig, Theme } from "@types";
import type { CodeBlockProps } from "./code-block.types";
import type { CSSObject } from "@emotion/react";
import type { ComponentStyleVariantConfig, Theme } from "@types";

import styled from "@emotion/styled";
import { getExcludedDOMProps, getStyleSlots } from "@system";
import { useMemo } from "react";

// Props for the styled component (excludes size since it's only used for typography calculation)
type StyledCodeBlockProps = Omit<CodeBlockProps, "size">;

// Make sure component name matches its type in the ThemeComponentVariants
const componentName = "CodeBlock";

// Generate child element class names for the component, should match available style slots
export const CodeBlockClasses = {
  root: "exp-textura_code-block",
};

// Set up style variant settings for the component (if more than "default"), using style slots
const getVariantConfig = (theme: Theme): ComponentStyleVariantConfig => ({
  critical: {
    root: {
      borderColor: theme.color.content.utility.critical,
    },
  },
});

const generateStyles = (props: StyledCodeBlockProps): CSSObject => {
  const { currentTheme: theme, variant, styleSlots: styleSlotsProp } = props;
  if (!theme) return {};

  // We are within an Emotion styled component, so we can utilize hooks
  // eslint-disable-next-line react-hooks/rules-of-hooks
  const styleSlots = useMemo(
    () =>
      getStyleSlots<StyledCodeBlockProps["styleSlots"]>(
        componentName,
        theme,
        variant,
        styleSlotsProp,
        getVariantConfig(theme),
      ),
    [theme, variant, styleSlotsProp],
  );

  return {
    display: "block",
    padding: "0",
    border: `${theme.toRem(theme.border.width.sm)} solid ${theme.color.border.actionHover}`,
    borderRadius: theme.toRem(theme.border.radius.sm),
    overflow: "hidden",

    "&[aria-disabled]": {
      pointerEvents: "none",
      opacity: 0.65,
      ...styleSlots?.disabled,
    },

    // the focused class as applied by the monaco editor
    "&:has(.view-overlays.focused)": {
      ...theme.focusRing,
      ...styleSlots?.focus,
    },

    ...styleSlots?.root,
  };
};

// Certain props passed to styled components should not be passed to the DOM element
const excludedDOMProps = getExcludedDOMProps();

// Define the styled component, exclude props from the DOM, generate themed JSS
export const StyledCodeBlock = styled("div", {
  shouldForwardProp: (prop) => !excludedDOMProps.includes(prop) && prop !== "size",
})<StyledCodeBlockProps>((props) => generateStyles(props));
